def build_runtime():
    layers = [
        DriverInputController(),
        DriverOutputController(),
        MwMicrowaveController(),
        MwOvenController(),
        MwGrillController(),
        MwSteamController(),
        ApplicationController(),
    ]
    return StaTableRuntime(layers, GLOBAL_VARIABLES)


if __name__ == "__main__":
    rt = build_runtime()
    print(f"StaTable runtime loaded: {len(rt.layers)} layers")
